function renderMapaBrasilSVG(containerId, mapaEstados) {
  var el = document.getElementById(containerId);
  if (!el) return;

  var maxCount = 1;
  BRASIL_ESTADOS.forEach(function(e) {
    var d = mapaEstados[e.s] || mapaEstados[e.n] || {};
    var c = d.count || 0;
    if (c > maxCount) maxCount = c;
  });

  var svgParts = '';
  BRASIL_ESTADOS.forEach(function(e) {
    var dados = mapaEstados[e.s] || mapaEstados[e.n] || {};
    var count = dados.count || 0;
    var pct = count / maxCount;

    var fill;
    if (count === 0) {
      fill = 'var(--bg-input)';
    } else {
      var light = Math.round(68 - pct * 43);
      var sat = Math.round(35 + pct * 50);
      fill = 'hsl(215,' + sat + '%,' + light + '%)';
    }

    svgParts += '<path d="' + e.d + '" fill="' + fill + '" stroke="var(--border)" stroke-width="0.6" stroke-linejoin="round" style="cursor:pointer;transition:opacity 0.15s" onmouseover="this.style.opacity=0.75;this.style.strokeWidth=\'1.5\'" onmouseout="this.style.opacity=1;this.style.strokeWidth=\'0.6\'">';
    svgParts += '<title>' + e.s + ' \u2014 ' + e.n + '\n' + count.toLocaleString('pt-BR') + ' reversas</title>';
    svgParts += '</path>';

    // Sigla e valor — tamanho adaptado ao estado
    var small = ['DF','SE','AL','RN','PB','ES'].indexOf(e.s) >= 0;
    var textFill = count > 0 ? '#fff' : 'var(--text-muted)';
    var fs = small ? 7 : 10;
    var small = ['DF','SE','AL','RN','PB','ES'].indexOf(e.s) >= 0;
    var textFill = count > 0 ? '#fff' : 'var(--text-muted)';
    var fs = small ? 9 : 12;
    svgParts += '<text x="' + e.cx + '" y="' + (e.cy - 1) + '" text-anchor="middle" font-size="' + fs + '" font-weight="700" fill="' + textFill + '" style="pointer-events:none">' + e.s + '</text>';
    if (count > 0) {
      var vs = small ? 7 : 9;
      svgParts += '<text x="' + e.cx + '" y="' + (e.cy + (small?8:11)) + '" text-anchor="middle" font-size="' + vs + '" fill="' + (count>0?'#ccc':'var(--text-muted)') + '" style="pointer-events:none">' + count.toLocaleString('pt-BR') + '</text>';
    }
  });

  // Legenda gradiente
  svgParts += '<defs><linearGradient id="legGrad" x1="0" y1="0" x2="0" y2="1">';
  svgParts += '<stop offset="0%" stop-color="hsl(215,85%,25%)"/><stop offset="100%" stop-color="hsl(215,35%,68%)"/>';
  svgParts += '</linearGradient></defs>';
 svgParts += '<rect x="810" y="180" width="18" height="130" fill="url(#legGrad)" rx="3" stroke="var(--border)" stroke-width="0.5"/>';
  svgParts += '<text x="819" y="170" text-anchor="middle" font-size="11" fill="var(--text-muted)">Reversas</text>';
  svgParts += '<text x="819" y="178" text-anchor="middle" font-size="10" font-weight="600" fill="var(--text)">' + maxCount.toLocaleString('pt-BR') + '</text>';
  svgParts += '<text x="819" y="322" text-anchor="middle" font-size="10" fill="var(--text-muted)">0</text>';

  el.innerHTML = '<svg viewBox="0 0 860 920" style="width:100%;max-height:520px" xmlns="http://www.w3.org/2000/svg">' + svgParts + '</svg>';
}
